def P(s,style='body'):
 return Paragraph(html.escape(s).replace('\n','<br/>'),ST[style])
def text(s):return ('text',s)
def sub(s):return ('sub',s)
def table(head,rows,widths=None):return ('table',head,rows,widths)
def photo(path,caption):return ('photo',path,caption)
def crop(path,box,caption,height=145):return ('crop',path,box,caption,height)
def notice(s):return ('notice',s)
def diagram():return ('diagram',)

class Crop(Flowable):
 def __init__(self,path,box,width,height):
  Flowable.__init__(self);self.path=path;self.box=box;self.width=width;self.height=height
 def draw(self):
  im=Image.open(self.path);iw,ih=im.size;x0,y0,x1,y1=self.box
  sc=min(self.width/(x1-x0),self.height/(y1-y0))
  dx=(self.width-(x1-x0)*sc)/2;dy=(self.height-(y1-y0)*sc)/2
  c=self.canv;c.saveState();p=c.beginPath();p.rect(dx,dy,(x1-x0)*sc,(y1-y0)*sc);c.clipPath(p,stroke=0,fill=0)
  c.drawImage(str(self.path),dx-x0*sc,dy-(ih-y1)*sc,width=iw*sc,height=ih*sc,mask='auto');c.restoreState()

class Diagram(Flowable):
 def __init__(self):Flowable.__init__(self);self.width=CW;self.height=300
 def draw(self):
  c=self.canv;c.setFont('K',8);c.setStrokeColor(ACC);c.setLineWidth(.8)
  for x,label,front in [(36,'앞면 / F',True),(286,'뒷면 / B',False)]:
   y=40;w=175;h=152
   p=c.beginPath();p.moveTo(x+5,y);p.curveTo(x-2,y+3,x,y+12,x+2,y+28);p.lineTo(x+18,y+h)
   p.lineTo(x+48,y+h);p.curveTo(x+59,y+h-30,x+116,y+h-30,x+127,y+h);p.lineTo(x+157,y+h)
   p.lineTo(x+w-2,y+28);p.curveTo(x+w,y+10,x+w+2,y+3,x+w-5,y);p.close();c.drawPath(p)
   c.setDash(3,3);c.line(x,y+h/2,x+w,y+h/2);c.line(x+w/2,y,x+w/2,y+h);c.setDash()
   if front:
    c.setFillColor(colors.HexColor('#EBA998'));c.circle(x+w/2,y+h/2,16,fill=1,stroke=0)
    c.setStrokeColor(ACC);c.ellipse(x+w/2-27,y+h/2-10,x+w/2+27,y+h/2+10)
    c.setFillColor(INK);c.drawCentredString(x+w/2,y+h/2-29,'116 x 102 mm')
   else:
    c.setFillColor(colors.HexColor('#D9C5AF'));c.rect(x,y+5,w,49,fill=1,stroke=0)
    c.setFillColor(INK);c.drawCentredString(x+w/2,y+27,'eollabyeol');c.drawCentredString(x+w/2,y+13,'384 x 108 mm')
   c.setStrokeColor(ACC);c.line(x,y-13,x+w,y-13);c.line(x,y-10,x,y-16);c.line(x+w,y-10,x+w,y-16)
   c.setFillColor(INK);c.drawCentredString(x+w/2,y-27,'W = 380 mm');c.drawCentredString(x+w/2,y+h+14,label)
   c.drawCentredString(x+w/2,y+h+33,'Y0: 측면 어깨선 / H = 330 mm')
  c.setFillColor(MUTED);c.drawString(10,278,'구성·배치 설명도 / 수치는 샘플 제작 시작 제안 / 축척 도면·재단 패턴 아님')

def render(title,pages,name):
 story=[];md=['# '+title,'','버전 v01 | 2026-11-19 | 외형 확정 / 실물 수치·공정은 초도 샘플 검증 전','','']
 for i,(heading,blocks) in enumerate(pages):
  if i:story.append(PageBreak())
  story.append(P(f'{i+1:02d}  {heading}','head'));md+=['## '+heading,'']
  for b in blocks:
   typ=b[0]
   if typ in ('text','sub'):
    story.append(P(b[1],'sub' if typ=='sub' else 'body'));md += [('### ' if typ=='sub' else '')+b[1],'']
   elif typ=='notice':
    t=Table([[P(b[1],'small')]],colWidths=[CW]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),colors.HexColor('#EEF3F0')),('BOX',(0,0),(-1,-1),.5,colors.HexColor('#CFDFD8')),('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),5)]));story.extend([t,Spacer(1,9)]);md += ['> '+b[1],'']
   elif typ=='table':
    heads,rows,widths=b[1:];widths=[CW*v for v in widths] if widths else [CW/len(heads)]*len(heads)
    data=[[P(s,'th') for s in heads]]+[[P(str(s),'cell') for s in row] for row in rows]
    t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),ACC),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,0),.6,ACC),('LINEBELOW',(0,1),(-1,-1),.4,colors.HexColor('#DCE3DF')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F5F7F5')])]))
    story.extend([t,Spacer(1,9)]);md += ['| '+' | '.join(heads)+' |','| '+' | '.join(['---']*len(heads))+' |']+['| '+' | '.join(str(s).replace('\n',' / ') for s in row)+' |' for row in rows]+['']
   elif typ=='photo':
    path,cap=b[1:];iw,ih=Image.open(path).size;story.extend([RLImage(str(path),width=CW,height=CW*ih/iw),Spacer(1,7),P(cap,'small')]);md += ['!['+cap+']('+path.name+')','']
   elif typ=='crop':
    path,box,cap,height=b[1:];story.extend([Crop(path,box,CW,height),Spacer(1,5),P(cap,'small')]);md += [f'원본 확대 영역: {path.name}, 좌표 {box}. {cap}','']
   elif typ=='diagram':story.extend([Diagram(),Spacer(1,8)]);md += ['배치 설명도: 본문 좌표와 제안 규격 참조.','']
 def footer(c,doc):
  c.setStrokeColor(colors.HexColor('#D6DFDA'));c.line(44,39,W-44,39);c.setFont('K',7.3);c.setFillColor(MUTED)
  c.drawString(44,26,'EOLLABYEOL / '+title+' / v01 / 2026.11.19');c.drawRightString(W-44,26,str(doc.page))
  c.setTitle(title);c.setAuthor('얼라별 상품 디자인 기록')
 doc=SimpleDocTemplate(str(OUT/(name+'.pdf')),pagesize=(W,H),leftMargin=44,rightMargin=44,topMargin=43,bottomMargin=53)
 doc.build(story,onFirstPage=footer,onLaterPages=footer)
 (OUT/(name+'.md')).write_text('\n'.join(md),encoding='utf-8')

